        features_json = N'["Vertical bars","Value labels on hover","Best for up to ~20 categories"]', options_template_json = N'{"chart":{"backgroundColor":"transparent","type":"column"},"xAxis":{"categories":"{{category}}"},"yAxis":{"title":{"text":null}},"legend":{"enabled":false},"series":[{"type":"column","name":"{{measure.label}}"}]}', modified_at = SYSUTCDATETIME()
